// ==== STREAM VIEWERS HEARTBEAT (inline next to "Прямая трансляция" label) ====
(function(){
  try {
    var CID_KEY = 'rm_viewer_cid';
    var cid = localStorage.getItem(CID_KEY);
    if (!cid) {
      cid = 'v_' + Math.random().toString(36).slice(2,10) + '_' + Date.now().toString(36);
      try { localStorage.setItem(CID_KEY, cid); } catch(e) {}
    }
    var tgUid = null;
    try { tgUid = window.Telegram && Telegram.WebApp && Telegram.WebApp.initDataUnsafe && Telegram.WebApp.initDataUnsafe.user && Telegram.WebApp.initDataUnsafe.user.id; } catch(e) {}
    if (tgUid) cid = 'tg_' + tgUid;

    var hbTimer = null, attachedTo = null;

    function findAnchor(){
      // 1. Public site "Прямая трансляция" label
      var spans = document.getElementsByTagName('span');
      for (var i=0;i<spans.length;i++){
        var s = spans[i];
        var tx = (s.textContent || '').trim();
        if (tx === 'Прямая трансляция') return s;
      }
      // 2. Webapp: stream trigger button (has pulse dot inside)
      var buttons = document.getElementsByTagName('button');
      for (var j=0;j<buttons.length;j++){
        var b = buttons[j];
        if (!b.offsetParent) continue;
        var pulse = b.querySelector('.animate-pulse');
        if (pulse && /трансл|vs|смотр/i.test(b.textContent || '')) return b;
      }
      return null;
    }

    function ensureBadge(anchor){
      if (attachedTo === anchor && document.getElementById('rm-viewers-badge')) return;
      removeBadge();
      var badge = document.createElement('span');
      badge.id = 'rm-viewers-badge';
      badge.style.cssText = 'display:inline-flex;align-items:center;gap:5px;margin-left:8px;padding:3px 8px;border-radius:999px;background:rgba(0,0,0,.5);color:#fff;font:600 11px/1 -apple-system,system-ui,Segoe UI,Roboto,sans-serif;vertical-align:middle;pointer-events:none;';
      badge.innerHTML = '<span style="width:5px;height:5px;background:#ff3b30;border-radius:50%;box-shadow:0 0 4px #ff3b30;animation:rmpulse 1.5s infinite"></span><span id="rm-viewers-count">…</span>';
      if (!document.getElementById('rm-viewers-style')){
        var st = document.createElement('style');
        st.id = 'rm-viewers-style';
        st.textContent = '@keyframes rmpulse{0%,100%{opacity:1}50%{opacity:.35}}';
        document.head.appendChild(st);
      }
      // Insert AFTER anchor, as sibling — safe: anchor is a label/button, not the video element
      if (anchor.parentNode) anchor.parentNode.insertBefore(badge, anchor.nextSibling);
      attachedTo = anchor;
    }

    function removeBadge(){
      var b = document.getElementById('rm-viewers-badge');
      if (b && b.parentNode) b.parentNode.removeChild(b);
      attachedTo = null;
    }

    function setCount(n){
      var el = document.getElementById('rm-viewers-count');
      if (!el) return;
      var word = (n%10===1 && n%100!==11) ? 'смотрит' : 'смотрят';
      el.textContent = '👁 ' + n + ' ' + word;
    }

    function ping(){
      fetch('/api/stream/heartbeat?client_id=' + encodeURIComponent(cid), { method: 'POST', keepalive: true })
        .then(function(r){ return r.json(); })
        .then(function(j){ if (j && typeof j.viewers === 'number') setCount(j.viewers); })
        .catch(function(){});
    }

    function start(){
      if (hbTimer) return;
      ping();
      hbTimer = setInterval(ping, 15000);
    }
    function stop(){
      if (hbTimer) { clearInterval(hbTimer); hbTimer = null; }
      removeBadge();
    }

    setInterval(function(){
      var anchor = findAnchor();
      if (anchor){
        if (!hbTimer) start();
        ensureBadge(anchor);
      } else {
        if (hbTimer) stop();
      }
    }, 1500);
  } catch(e) { console.warn('viewers init failed', e); }
})();
